from __future__ import annotations

from datetime import datetime, timedelta, timezone


def _parse_utc_timestamp(utc_iso: str) -> datetime:
    text = utc_iso.strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"

    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        raise ValueError("timestamp must be timezone-aware")
    return dt.astimezone(timezone.utc)


def format_local_run_time(utc_iso: str, user_offset_minutes: int) -> str:
    utc_dt = _parse_utc_timestamp(utc_iso)

    if user_offset_minutes < -840 or user_offset_minutes > 840:
        raise ValueError("user_offset_minutes out of range")

    # user_offset_minutes follows common API conventions (e.g. +600 for UTC+10)
    local_dt = utc_dt + timedelta(minutes=user_offset_minutes)
    return local_dt.strftime("%Y-%m-%d %H:%M")

