import pytest

from schedule import format_local_run_time


def test_happy_path_utc_to_plus_ten():
    assert format_local_run_time("2026-05-07T12:30:00Z", 600) == "2026-05-07 22:30"


def test_edge_case_crosses_previous_day_for_negative_offset():
    assert format_local_run_time("2026-05-07T02:15:00Z", -300) == "2026-05-06 21:15"


def test_boundary_condition_max_supported_positive_offset():
    assert format_local_run_time("2026-01-01T00:00:00+00:00", 840) == "2026-01-01 14:00"


def test_unexpected_input_naive_timestamp_raises():
    with pytest.raises(ValueError):
        format_local_run_time("2026-05-07T12:30:00", 600)
